import json
import logging
import time
import zmq
from .pc_server_exceptions import MessageOutOfOrderException, TimeoutExceededException, UePcConnectionnException
import sys

logger = logging.getLogger('ute_ue')


class PcServer(object):
    """Pc Server class represents object which connects to PcServer over ZMQ socket."""

    sending_timeout = 1000
    recieving_timeout = 1000
    retry_times_for_sending = 3
    retry_times_for_recieving = 3
    global_timeout = 20

    def __init__(self):
        """
        Pc Server

        :return:                    None
        :rtype:                     None
        """
        self.context = zmq.Context()
        self._context = self.context.instance()
        self._poller = zmq.Poller()
        self._pusher = zmq.Poller()
        self.stop = False
        self.failed = False

    def _setup_dealer_connection_with_socket(self, host, port):
        try:
            _socket = self._context.socket(zmq.DEALER)
            _socket.setsockopt(zmq.LINGER, 0)
            _socket.connect("tcp://{}:{}".format(host, port))
            self._pusher.register(_socket, zmq.POLLOUT)
            return _socket
        except Exception as e:
            logger.critical("Error: {} {}".format(type(e), e))
            raise UePcConnectionnException(
                "Failed establishing connection to [{}][{}]".format(host, port))

    def _setup_router_connection_with_socket(self, host, port):
        try:
            _socket = self._context.socket(zmq.ROUTER)
            _socket.setsockopt(zmq.LINGER, 0)
            _socket.connect("tcp://{}:{}".format(host, port))
            self._poller.register(_socket, zmq.POLLIN)
            return _socket
        except Exception as e:
            logger.critical("Error: {} {}".format(type(e), e))
            raise UePcConnectionnException(
                "Failed establishing connection to [{}][{}]".format(host, port))

    def _get_sockopt_method(self, socket):
        if sys.version_info[0] >= 3:
            return socket.setsockopt_string
        else:
            return socket.setsockopt

    def _setup_subscriber_connection_with_socket(self, host, port, topic=""):
        try:
            _socket = self._context.socket(zmq.SUB)
            _socket.setsockopt(zmq.LINGER, 0)
            _socket.connect("tcp://{}:{}".format(host, port))
            self._get_sockopt_method(_socket)(zmq.SUBSCRIBE, topic)
            self._poller.register(_socket, zmq.POLLIN)
            return _socket
        except Exception as e:
            logger.critical("Error: {} {}".format(type(e), e))
            raise UePcConnectionnException(
                "Failed establishing connection to [{}][{}]".format(host, port))

    def _send_message_in_non_blocking_way_to_server(self, message, outgoing_socket):
        """
        Method for sending message to PC Server with initial probe to see if message will reach the recepient

        :param message:             Message to send over socket
        :type message:              string

        :return:                    True if message send succeded, False if messaged send failed
        :rtype:                     bool
        """
        retried = 0
        while retried < self.retry_times_for_sending:
            if self.stop:
                break
            try:
                socket = dict(self._pusher.poll(self.sending_timeout))
                if outgoing_socket.socket in socket:
                    outgoing_socket.socket.send_string(message)
                    logger.info("Sending message: '{}' succeded".format(message))
                    return True
                else:
                    retried += 1
            except Exception as e:
                logger.warning("Exception occured when sending message: {}".format(e))
                raise
        logger.warning("Sending message: '{}' failed".format(message))
        return False

    def _can_communicate_with_server(self, *outgoing_sockets):
        """
        Method checks if socket is free

        :return:    True/False
        :rtype:     bool
        """
        retried = 0
        while retried < self.retry_times_for_sending:
            for SOCKET in outgoing_sockets:
                try:
                    socket = dict(self._pusher.poll(self.sending_timeout))
                    if SOCKET.socket in socket:
                        return True
                    else:
                        retried += 1
                except Exception as e:
                    logger.warning("Exception when probing server: {}".format(e))
                    raise
        logger.warning("Unable to communicate with UePc Server")
        return False

    def _recieve_messages_in_non_blocking_way(self, message_dictionary, *recieve_sockets):
        """
        Method for recieving a dictionary of items.
        Method will wait for global timeout and if no new messages are recieved in that time it will return.

        :return:            Dictionary containing array of messages from QXDM_MESSAGES and COMMAND_OUTPUT
        :rtype:             dict
        """
        retries = 0
        message_dictionary = self._initialize_message_dictionary(message_dictionary, recieve_sockets)
        while retries < self.retry_times_for_recieving:
            try:
                # logger.info("_recieve_messages_in_non_blocking_way before . message_dictionary [{}]".format(message_dictionary))
                retries, message_dictionary = self._receive(message_dictionary, recieve_sockets, retries)
                # logger.info("_recieve_messages_in_non_blocking_way after. message_dictionary [{}]".format(message_dictionary))
                if self.failed:
                    return
            except KeyboardInterrupt:
                break
            except Exception as e:
                logger.warning("Exception occured when trying to recieve message: {}".format(e))
                raise
        self._logging(message_dictionary)
        return message_dictionary

    def _receive(self, message_dictionary, recieve_sockets, retries):
        messages_recieved = False
        sockets = dict(self._poller.poll(self.recieving_timeout))
        for SOCKET in recieve_sockets:
            try:
                if SOCKET.socket in sockets:
                    message = SOCKET.socket.recv_string()
                    message = json.loads(message)
                    # logger.info("_receive. message [{}]".format(message))
                    message_dictionary[SOCKET.dictionary].append(message)
                    # logger.info("_receive. message_dictionary [{}]".format(message_dictionary))
                    messages_recieved = True
            except UnicodeDecodeError:
                pass
        retries = self._update_retries_counter(messages_recieved, retries)
        return retries, message_dictionary

    def _update_retries_counter(self, messages_recieved, retries):
        if not messages_recieved:
            retries += 1
        else:
            retries = 0
        return retries

    def _initialize_message_dictionary(self, message_dictionary, recieve_sockets):
        if not message_dictionary:
            message_dictionary = {}
        for SOCKET in recieve_sockets:
            if not message_dictionary.get(SOCKET.dictionary):
                message_dictionary[SOCKET.dictionary] = []
        return message_dictionary

    def _prepare_message(self, command, **kwargs):
        kwargs["command"] = command.value
        return json.dumps(kwargs)

    def _send(self, command, input_socket, timeout_overwrite=0, *recieve_sockets, **kwargs):
        recovery_mode = kwargs.get("recovery_mode", False)
        json_message = self._prepare_message(command, **kwargs)
        if not self._send_message_in_non_blocking_way_to_server(json_message, input_socket):
            logger.warning("Failed sending message [{}] Received messageto [UE_PC]".format(command))
            return False, {}
        if recovery_mode:
            return True, {}
        return self._wait_for_reply(command, recieve_sockets, timeout_overwrite)

    def _wait_for_reply(self, command, recieve_sockets, timeout_overwrite):
        time_start = time.time()
        current_time = time.time()
        messages = {"COMMAND_OUTPUT": []}
        while True:
            self._check_fail(command)
            messages = self._recieve_messages_in_non_blocking_way(messages, *recieve_sockets)
            result = self._check_messages(command, messages)
            if result is not None:
                return result, messages
            current_time = time.time()
            if timeout_overwrite < 0 and (current_time - time_start <= 1800):
                continue
            elif timeout_overwrite < 0 and (current_time - time_start >= 1800):
                raise TimeoutExceededException(
                    "Exception timeout exceeded while waiting for response message from PC Server to [{}] "
                    "command".format(command.value))
            self._check_timeout(command, current_time, time_start, timeout_overwrite)

    def _check_messages(self, command, messages):
        for message in messages["COMMAND_OUTPUT"]:
            if message["command"] == command.value and message["result"] == "OK":
                logger.info("Command [{}] executed successfully".format(command))
                return True
            if message["command"] == command.value and message["result"] == "FAIL":
                logger.warning("Command [{}] failed: {}".format(command, message["metadata"]))
                return False
            if message["command"] != command.value and message["result"] == "FAIL":
                logger.warning("Recieved out of order fail message for command [{}] with error '{}' "
                               "instead of [{}]".format(message["command"], message["metadata"], command))
                raise MessageOutOfOrderException("Recieved out of order fail message for command [{}] with error '{}' "
                                                 "instead of [{}]".format(message["command"], message["metadata"], command))

    def _check_timeout(self, command, current_time, time_start, timeout_overwrite):
        if (current_time - time_start >= self.global_timeout) and not timeout_overwrite:
            logger.warning("Global timeout exceeded while waiting for response message from PC Server to [{}] "
                           "command".format(command.value))
            raise TimeoutExceededException(
                "Global timeout exceeded while waiting for response message from PC Server to [{}] "
                "command".format(command.value))
        elif (current_time - time_start >= timeout_overwrite) and timeout_overwrite:
            logger.warning("Timer exceeded while waiting for response message from PC Server to [{}] "
                           "command".format(command.value))
            raise TimeoutExceededException(
                "Timer exceeded while waiting for response message from PC Server to [{}] command".format(command.value))

    def _check_fail(self, command):
        if self.failed:
            logger.warning("Fail occured while waiting for response message from PC Server to [{}] "
                           "command".format(command.value))
            raise TimeoutExceededException(
                "Fail occured while waiting for response message from PC Server to [{}] command".format(command.value))

    def _logging(self, message_dictionary):
        if bool(message_dictionary['COMMAND_OUTPUT']):
            if message_dictionary['COMMAND_OUTPUT'][0]['command'] != 'QXDM->GET_LOG_ITEMS':
                logger.info("Received message: {}".format(json.dumps(message_dictionary)))
